// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_listTpClssCd_3", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })())	!== '02'); } }, { id: "if_listTpClssCd_4", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })())	!== '02'); } }, { id: "if_listTpClssCd_5", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })())	!== '02'); } }, { id: "if_listTpClssCd_6", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })())	!== '02'); } }, { id: "if_listTpClssCd_7", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })())	!== '02'); } }, { id: "if_listTpClssCd_8", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })())	!== '02'); } }, { id: "if_listTpClssCd_9", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })())	!== '02'); } }, { id: "if_listTpClssCd_10", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })())	!== '02'); } }, { id: "if_listTpClssCd_11", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })())	!== '02'); } }, { id: "if_lgshrhdNm", fn: function(){ return ((dma_comInfo.get("lgshrhdNm") ?? (() => { throw new Error("unresolved:" + "comInfo.lgshrhdNm"); })()) !==''); } }, { id: "if_ovr1pctOwnrNm", fn: function(){ return ((dma_comInfo.get("ovr1pctOwnrNm") ?? (() => { throw new Error("unresolved:" + "comInfo.ovr1pctOwnrNm"); })()) !==''); } }, { id: "if_listTpClssCd_12", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })())	!== '02'); } }, { id: "if_ldMktTpCd", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.ldMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ldMktTpCd")) ==='2'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
