        { childId: "ipt_sum6", fn: function () { return String((String(dma_comInfo.get("lgshrhdShrRt")) + String(dma_comInfo.get("lgshrhdRelprnShrRt")))); } },
        { childId: "ipt_sum7", fn: function () { return String((String(dma_comInfo.get("lgshrhdBfpubofrSaleShrs")) + String(dma_comInfo.get("lssrpBfpubofrSaleShrs")))); } },
        { childId: "ipt_sum8", fn: function () { return String((String(dma_comInfo.get("lgshrhdBfpubofrOferShrs")) + String(dma_comInfo.get("lssrpBfpubofrOferShrs")))); } },
        { childId: "ipt_sum9", fn: function () { return String((String(dma_comInfo.get("lgshrhdAfpubofrShrs")) + String(dma_comInfo.get("lssrpAfpubofrShrs")))); } },
        { childId: "ipt_sum10", fn: function () { return String((String(dma_comInfo.get("lgshrhdAfpubofrShrRt")) + String(dma_comInfo.get("lssrpAfpubofrShrRt")))); } },
        { childId: "ipt_sum11", fn: function () { return String((String(dma_comInfo.get("ovr1pctCmstkShrs")) + String(dma_comInfo.get("ovr1pctPrefstkShrs")))); } },
        { childId: "ipt_sum12", fn: function () { return String((String(dma_comInfo.get("ovr1pctRelprnCmstkShrs")) + String(dma_comInfo.get("ovr1pctRelprnPrefstkShrs")))); } },
        { childId: "ipt_sum13", fn: function () { return String((String(dma_comInfo.get("ovr1pctCmstkShrs")) + String(dma_comInfo.get("ovr1pctRelprnCmstkShrs")))); } },
        { childId: "ipt_sum14", fn: function () { return String((String(dma_comInfo.get("ovr1pctPrefstkShrs")) + String(dma_comInfo.get("ovr1pctRelprnPrefstkShrs")))); } },
        { childId: "ipt_sum15", fn: function () { return String(((String(dma_comInfo.get("ovr1pctCmstkShrs")) + String(dma_comInfo.get("ovr1pctPrefstkShrs"))) + (String(dma_comInfo.get("ovr1pctRelprnCmstkShrs")) + String(dma_comInfo.get("ovr1pctRelprnPrefstkShrs"))))); } },
        { childId: "ipt_sum16", fn: function () { return String((String(dma_comInfo.get("ovr1pctShrRt")) + String(dma_comInfo.get("ovr1pctRelprnShrRt")))); } },
        { childId: "ipt_sum17", fn: function () { return String((String(dma_comInfo.get("ovr1pctBfpubofrSaleShrs")) + String(dma_comInfo.get("o1psrpBfpubofrSaleShrs")))); } },
        { childId: "ipt_sum18", fn: function () { return String((String(dma_comInfo.get("ovr1pctBfpubofrOferShrs")) + String(dma_comInfo.get("o1psrpBfpubofrOferShrs")))); } },
        { childId: "ipt_sum19", fn: function () { return String((String(dma_comInfo.get("ovr1pctAfpubofrShrs")) + String(dma_comInfo.get("o1psrpAfpubofrShrs")))); } },
        { childId: "ipt_sum20", fn: function () { return String((String(dma_comInfo.get("ovr1pctAfpubofrShrRt")) + String(dma_comInfo.get("o1psrpAfpubofrShrRt")))); } },
        { childId: "ipt_sum21", fn: function () { return String((String(dma_comInfo.get("minshrhdCmstkShrs")) + String(dma_comInfo.get("minshrhdPrefstkShrs")))); } },
        { childId: "ipt_sum23", fn: function () { return String(((String(dma_comInfo.get("minshrhdCmstkShrs")) + (String(dma_comInfo.get("lgshrhdCmstkShrs")) + String(dma_comInfo.get("lgshrhdRelprnCmstkShrs")))) + (String(dma_comInfo.get("ovr1pctCmstkShrs")) + String(dma_comInfo.get("ovr1pctRelprnCmstkShrs"))))); } },
        { childId: "ipt_sum24", fn: function () { return String(((String(dma_comInfo.get("minshrhdPrefstkShrs")) + (String(dma_comInfo.get("lgshrhdPrefstkShrs")) + String(dma_comInfo.get("lgshrhdRelprnPrefstkShrs")))) + (String(dma_comInfo.get("ovr1pctPrefstkShrs")) + String(dma_comInfo.get("ovr1pctRelprnPrefstkShrs"))))); } },
        { childId: "ipt_sum25", fn: function () { return String((((((String(dma_comInfo.get("minshrhdCmstkShrs")) + String(dma_comInfo.get("minshrhdPrefstkShrs"))) + (String(dma_comInfo.get("lgshrhdCmstkShrs")) + String(dma_comInfo.get("lgshrhdPrefstkShrs")))) + (String(dma_comInfo.get("lgshrhdRelprnCmstkShrs")) + String(dma_comInfo.get("lgshrhdRelprnPrefstkShrs")))) + (String(dma_comInfo.get("ovr1pctCmstkShrs")) + String(dma_comInfo.get("ovr1pctPrefstkShrs")))) + (String(dma_comInfo.get("ovr1pctRelprnCmstkShrs")) + String(dma_comInfo.get("ovr1pctRelprnPrefstkShrs"))))); } },
        { childId: "ipt_sum26", fn: function () { return String(((((String(dma_comInfo.get("minshrhdShrRt")) + String(dma_comInfo.get("ovr1pctShrRt"))) + String(dma_comInfo.get("ovr1pctRelprnShrRt"))) + String(dma_comInfo.get("lgshrhdShrRt"))) + String(dma_comInfo.get("lgshrhdRelprnShrRt")))); } },
        { childId: "ipt_sum27", fn: function () { return String(((((String(dma_comInfo.get("lgshrhdBfpubofrSaleShrs")) + String(dma_comInfo.get("lssrpBfpubofrSaleShrs"))) + String(dma_comInfo.get("ovr1pctBfpubofrSaleShrs"))) + String(dma_comInfo.get("o1psrpBfpubofrSaleShrs"))) + String(dma_comInfo.get("minshrhdBfpubofrSaleShrs")))); } },
        { childId: "ipt_sum28", fn: function () { return String(((((String(dma_comInfo.get("lgshrhdBfpubofrOferShrs")) + String(dma_comInfo.get("lssrpBfpubofrOferShrs"))) + String(dma_comInfo.get("ovr1pctBfpubofrOferShrs"))) + String(dma_comInfo.get("o1psrpBfpubofrOferShrs"))) + String(dma_comInfo.get("minshrhdBfpubofrOferShrs")))); } },
        { childId: "ipt_sum29", fn: function () { return String((((String(dma_comInfo.get("minshrhdAfpubofrShrs")) + (String(dma_comInfo.get("lgshrhdAfpubofrShrs")) + String(dma_comInfo.get("lssrpAfpubofrShrs")))) + String(dma_comInfo.get("ovr1pctAfpubofrShrs"))) + String(dma_comInfo.get("o1psrpAfpubofrShrs")))); } },
        { childId: "ipt_sum30", fn: function () { return String(((((String(dma_comInfo.get("lgshrhdAfpubofrShrRt")) + String(dma_comInfo.get("lssrpAfpubofrShrRt"))) + String(dma_comInfo.get("ovr1pctAfpubofrShrRt"))) + String(dma_comInfo.get("o1psrpAfpubofrShrRt"))) + String(dma_comInfo.get("minshrhdAfpubofrShrRt")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf07140.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_print_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_print_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_print_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        fn_print()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07140.btn_print_onclick' }); }
};


